import{useState}from'react';import{Alert,Pressable,StyleSheet,Text,View}from'@/platform/react-native';import{useLocalSearchParams}from'@/router';import{useMutation,useQuery,useQueryClient}from'@tanstack/react-query';import{api}from'@/lib/api';import{Badge,Button,Card,EmptyState,Muted,Screen,useAppTheme}from'@/components/UI';
export default function FormalVoting(){const{id}=useLocalSearchParams<{id:string}>();const{palette}=useAppTheme();const qc=useQueryClient();const[selected,setSelected]=useState<Record<string,string>>({});const q=useQuery<any[]>({queryKey:['formal-ballots',id],queryFn:async()=>(await api.get(`/communities/${id}/formal-ballots`)).data});return <Screen scroll><Muted>Eligibility · One member one vote · quorum · audit trail</Muted>{!q.data?.length?<EmptyState title="No formal ballots" body="Important community votes are separated from casual polls."/>:q.data.map((b:any)=><Ballot key={b.Id} b={b} selected={selected[b.Id]} setSelected={(v:string)=>setSelected({...selected,[b.Id]:v})} refresh={()=>qc.invalidateQueries({queryKey:['formal-ballots',id]})}/>)}</Screen>}
function Ballot({b,selected,setSelected,refresh}:{b:any;selected?:string;setSelected:(v:string)=>void;refresh:()=>void}){const{palette}=useAppTheme();const detail=useQuery<any>({queryKey:['ballot',b.Id],queryFn:async()=>(await api.get(`/formal-ballots/${b.Id}`)).data});const vote=useMutation({mutationFn:()=>api.post(`/formal-ballots/${b.Id}/vote`,{optionId:selected}),onSuccess:(r:any)=>{Alert.alert('Vote recorded',`Your receipt: ${r.data.receipt.slice(0,12)}…`);refresh()},onError:(e:any)=>Alert.alert('Unable to vote',e.response?.data?.message||e.message)});return <Card><View style={s.top}><Text style={[s.title,{color:palette.text}]}>{b.Title}</Text><Badge text={b.Status}/></View><Muted>{b.Description}</Muted><Muted>{b.VoteCount}/{b.EligibleCount} votes · quorum {b.QuorumPercent}% · {b.IsAnonymous?'anonymous ballot':'named ballot'}</Muted>{detail.data?.options?.map((o:any)=><Pressable key={o.Id} onPress={()=>setSelected(o.Id)} style={[s.opt,{borderColor:selected===o.Id?palette.primary:palette.border,backgroundColor:selected===o.Id?palette.primarySoft:palette.surface}]}><Text style={{color:palette.text,fontWeight:'800'}}>{o.Label}</Text>{o.VoteCount!=null?<Muted>{o.VoteCount} vote(s)</Muted>:null}</Pressable>)}<Button title={b.HasVoted?'Vote recorded':b.IsEligible?'Cast vote':'Not eligible'} disabled={b.HasVoted||!b.IsEligible||!selected} onPress={()=>vote.mutate()}/></Card>};const s=StyleSheet.create({top:{flexDirection:'row',justifyContent:'space-between',gap:10},title:{fontSize:16,fontWeight:'900',flex:1},opt:{borderWidth:1,borderRadius:13,padding:12,marginTop:8}})
